  "items": [
    {
      "title": "German Federal Election 2025 – Official Election Results (Bundestagswahl 2025)",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/2025/ergebnisse/opendata.html",
      "justification": "Official open dataset published by Germany's Federal Returning Officer (Bundeswahlleiterin) for the February 23, 2025 federal election. Provides downloadable CSV and XML files containing party votes, constituency results, state-level results, and nationwide totals. Includes first and second votes, electoral district identifiers, and comparative data from the 2021 election. Particularly useful for analyzing electoral shifts, party performance, and geographic voting patterns."
    },
    {
      "title": "German Federal Election 2021 – Official Election Results (Bundestagswahl 2021)",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/2021/ergebnisse.html",
      "justification": "Official election results for Germany's September 26, 2021 federal election. Contains constituency-level, state-level, and nationwide voting results, including party vote shares, turnout, and seat distributions. The data also account for the partial repeat election held in Berlin in 2024. Useful for examining political changes following Angela Merkel's chancellorship and comparing voting behavior between the 2021 and 2025 federal elections."
    },
    {
      "title": "GERDA: German Election Database – Federal, State, Municipal, and European Elections",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Comprehensive research database containing German election results at the municipality, county, and constituency levels. Covers federal elections through 2025, European Parliament elections through 2024, and numerous state and municipal elections during the 2020s. Provides original election results alongside geographically harmonized datasets that facilitate comparisons across years. Available in CSV, Excel, and RDS formats. Particularly valuable for longitudinal electoral analysis, spatial statistics, and studying regional political polarization."
    },
    {
      "title": "GERDA: The German Election Database – Scientific Data Publication",
      "url_or_doi": "https://doi.org/10.1038/s41597-025-04811-5",
      "justification": "Peer-reviewed dataset publication in Scientific Data (2025) describing a comprehensive database of German elections. Includes municipality-level results from federal, state, and municipal elections, with geographic harmonization to support longitudinal analysis. Provides methodological documentation on data collection, processing, and geographic standardization. Particularly suitable for academic research requiring reproducible and well-documented election datasets."
    },
    {
      "title": "European Parliament Election 2024 – Official German Election Results",
      "url_or_doi": "https://www.bundeswahlleiterin.de/europawahlen/2024/ergebnisse/opendata.html",
      "justification": "Official open dataset covering Germany's June 9, 2024 European Parliament election. Contains party-level voting results, turnout figures, and geographic breakdowns at the federal, state, and district levels. Provides machine-readable CSV and XML files. Useful for investigating European election participation, regional differences in party support, and the performance of established and emerging political parties in Germany."
    },
    {
      "title": "European Parliament Election Results 2024 – European Parliament Open Data",
      "url_or_doi": "https://results.elections.europa.eu/en/tools/download-datasheets/",
      "justification": "Official European Parliament election data repository offering downloadable results for the 2024 European elections, including Germany. Contains country-level party results, turnout figures, political group affiliations, and historical European election data. Supports downloads in structured formats, including JSON. Particularly useful for comparing German electoral behavior with other European Union member states and examining changes in European political representation."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Election Survey Data 2021–2025",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Major academic election research program maintained by GESIS – Leibniz Institute for the Social Sciences. Provides survey datasets covering the 2021 and 2025 German federal elections, including voter preferences, party identification, political attitudes, candidate evaluations, and voting decisions. Includes cross-sectional, panel, and rolling cross-sectional surveys. Particularly useful for analyzing individual-level electoral behavior and explaining changes in voting preferences. Registration is required to access datasets."
    },
    {
      "title": "German Longitudinal Election Study – 2025 Federal Election Surveys",
      "url_or_doi": "https://www.gesis.org/en/gles/2025-federal-election",
      "justification": "Collection of election research datasets specifically covering Germany's 2025 federal election. Includes post-election surveys, rolling cross-sectional surveys, tracking studies, candidate studies, and nomination studies. Contains information on voter attitudes, political preferences, campaign dynamics, and electoral decision-making. Particularly suitable for investigating why voters supported different parties during the 2025 election and how preferences changed throughout the campaign."
    },
    {
      "title": "GLES Cross-Section 2021 – Pre-Election and Post-Election Surveys",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Representative survey datasets associated with Germany's 2021 federal election, including GLES Pre-Election 2021 (ZA7700), Post-Election 2021 (ZA7701), and the combined Pre- and Post-Election study (ZA7702). Cover electoral participation, party preferences, political attitudes, and voting decisions. Particularly useful for studying voter behavior during the 2021 election and establishing a baseline for comparisons with the 2025 federal election."
    },
    {
      "title": "German State Election Studies – GESIS Election Research Data",
      "url_or_doi": "https://www.gesis.org/en/elections/german-state-elections",
      "justification": "GESIS collection of representative survey datasets covering elections to Germany's state parliaments (Landtagswahlen). Includes several elections during the 2020s, such as Brandenburg, Saxony, and Thuringia in 2024 and Hamburg in 2025. Provides information about voting intentions, party preferences, political attitudes, and demographic characteristics. Particularly useful for analyzing regional political dynamics and differences between federal and state elections."
    },
    {
      "title": "Brandenburg State Election 2024 – GESIS Election Study (ZA8978)",
      "url_or_doi": "https://doi.org/10.4232/1.14537",
      "justification": "Academic survey dataset covering the 2024 Brandenburg state election. Available through GESIS, it provides survey-based information relevant to electoral behavior, political preferences, and party competition. Particularly valuable for investigating electoral developments in eastern Germany and understanding voter support for parties such as the SPD, AfD, and Bündnis Sahra Wagenknecht (BSW)."
    },
    {
      "title": "Thuringia State Election 2024 – GESIS Election Study (ZA8977)",
      "url_or_doi": "https://doi.org/10.4232/1.14536",
      "justification": "GESIS election survey dataset associated with the 2024 Thuringia state parliamentary election. Supports research into voter preferences, political attitudes, and electoral behavior in eastern Germany. Particularly relevant for studying regional party competition, the rise of the AfD, and changing support for traditional political parties."
    },
    {
      "title": "Saxony State Election 2024 – GESIS Election Study (ZA8976)",
      "url_or_doi": "https://doi.org/10.4232/1.14535",
      "justification": "Academic election survey dataset covering the 2024 Saxony state election. Provides survey data suitable for investigating voter attitudes, political preferences, and electoral choices. Useful for comparing electoral behavior across eastern German states and examining regional political polarization and party competition."
    },
    {
      "title": "Hamburg State Election 2025 – GESIS Election Study (ZA9153)",
      "url_or_doi": "https://doi.org/10.4232/1.14796",
      "justification": "GESIS survey dataset associated with Hamburg's 2025 state parliamentary election. Provides information suitable for studying electoral behavior, political attitudes, and party preferences. Particularly useful for comparing urban electoral patterns with those observed in other German states and examining differences between state and federal electoral dynamics."
    },
    {
      "title": "German Election Results Since 1946 – Konrad Adenauer Foundation",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Historical election data collection maintained by the Konrad Adenauer Foundation. Provides results for German federal, European Parliament, and state elections, including elections held during the 2020s. Contains historical party results and representative electoral statistics. Particularly useful for examining long-term electoral trends, changing party systems, and the historical context of recent German elections."
    },
    {
      "title": "German Federal Election 2025 – Representative Electoral Statistics by Age and Gender",
      "url_or_doi": "https://bundeswahlleiterin.de/bundestagswahlen/2025/ergebnisse/repraesentative-wahlstatistik.html",
      "justification": "Official statistical dataset from Germany's Federal Returning Officer documenting electoral participation and voting behavior during the 2025 federal election. Provides tabular data on turnout and party voting patterns by age group and gender, including comparisons with historical elections. Particularly valuable for demographic analyses of voting behavior, generational differences in party support, and gender-related electoral trends."
    },
    {
      "title": "German Longitudinal Election Study – Rolling Cross-Section 2025 (ZA10101)",
      "url_or_doi": "https://www.gesis.org/en/gles/2025-federal-election",
      "justification": "Survey dataset examining the evolution of political attitudes and voting preferences during Germany's 2025 federal election campaign. Data collection covered January through March 2025, including periods before and after election day. Particularly useful for investigating campaign effects, changes in voting intentions, political issue salience, and the relationship between campaign events and electoral decisions."
    },
    {
      "title": "GERDA – German Municipal Election Results During the 2020s",
      "url_or_doi": "https://www.german-elections.com/",
      "justification": "Municipality-level election results covering local council and other municipal elections across Germany, including elections held during the 2020s. Provides both original and harmonized election data in machine-readable formats. Useful for examining local voting patterns, regional political differences, and relationships between municipal, state, and federal electoral outcomes."
    }
  ]
}
